ALTER TABLE salud_u.solicitud_cita ADD COLUMN id_cita uuid NULL;
ALTER TABLE salud_u.solicitud_cita ADD COLUMN asignado_en timestamptz NULL;
ALTER TABLE salud_u.solicitud_cita ADD COLUMN asignado_por uuid NULL REFERENCES salud_u.principal(id) ON DELETE RESTRICT;
ALTER TABLE salud_u.solicitud_cita DROP CONSTRAINT cita_solicitud_status;
ALTER TABLE salud_u.solicitud_cita ADD CONSTRAINT solicitud_cita_estado_valido CHECK (estado IN ('PENDING', 'CANCELLED', 'ASSIGNED'));
CREATE TABLE salud_u.cita (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),id_paciente uuid NOT NULL REFERENCES salud_u.paciente(id) ON DELETE RESTRICT,id_cupo uuid NOT NULL REFERENCES salud_u.cupo_disponibilidad(id) ON DELETE RESTRICT,tipo_cita text NOT NULL,estado text NOT NULL DEFAULT 'SCHEDULED',id_personal_asignado uuid NOT NULL REFERENCES salud_u.personal(id) ON DELETE RESTRICT,programada_para timestamptz NOT NULL,creado_en timestamptz NOT NULL DEFAULT now(),CONSTRAINT cita_type_valid CHECK(tipo_cita IN('INITIAL','SPECIALTY')),CONSTRAINT cita_status_valid CHECK(estado IN('SCHEDULED','CHECKED_IN','ATTENDED','CANCELLED','NO_SHOW')));
ALTER TABLE salud_u.solicitud_cita ADD CONSTRAINT cita_solicitud_cita_fk FOREIGN KEY(id_cita) REFERENCES salud_u.cita(id) ON DELETE RESTRICT;
CREATE TABLE salud_u.evento_estado_cita(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),id_cita uuid NOT NULL REFERENCES salud_u.cita(id) ON DELETE RESTRICT,estado_anterior text NULL,estado_nuevo text NOT NULL,ocurrido_en timestamptz NOT NULL DEFAULT now(),id_actor uuid NOT NULL REFERENCES salud_u.principal(id) ON DELETE RESTRICT);
ALTER TABLE salud_u.cita ENABLE ROW LEVEL SECURITY; ALTER TABLE salud_u.cita FORCE ROW LEVEL SECURITY; ALTER TABLE salud_u.evento_estado_cita ENABLE ROW LEVEL SECURITY; ALTER TABLE salud_u.evento_estado_cita FORCE ROW LEVEL SECURITY; CREATE POLICY cita_migrator ON salud_u.cita FOR ALL TO ${migrator_role} USING(true) WITH CHECK(true); CREATE POLICY cita_event_migrator ON salud_u.evento_estado_cita FOR ALL TO ${migrator_role} USING(true) WITH CHECK(true);
CREATE FUNCTION salud_u.asignar_solicitud_cita(p_solicitud_id uuid,p_cupo_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=salud_u,pg_temp AS $$ DECLARE r record;s record;id_cita_creada uuid;actor uuid:=salud_u.id_actor_actual();BEGIN PERFORM salud_u.requerir_administrativo(); SELECT * INTO r FROM salud_u.solicitud_cita WHERE id=p_solicitud_id FOR UPDATE; IF NOT FOUND OR r.estado<>'PENDING' THEN RAISE EXCEPTION 'La solicitud no está pendiente' USING ERRCODE='23514'; END IF; SELECT * INTO s FROM salud_u.cupo_disponibilidad WHERE id=p_cupo_id FOR UPDATE; IF NOT FOUND OR s.estado<>'PUBLISHED' OR s.inicia_a<=now() OR s.cantidad_reservada>=s.capacidad THEN RAISE EXCEPTION 'El cupo no está disponible' USING ERRCODE='P0001'; END IF; IF (r.tipo_cita='INITIAL' AND s.id_especialidad IS NOT NULL) OR (r.tipo_cita='SPECIALTY' AND s.id_especialidad IS DISTINCT FROM r.id_especialidad) THEN RAISE EXCEPTION 'El cupo no es compatible con la solicitud' USING ERRCODE='23514'; END IF; IF EXISTS(SELECT 1 FROM salud_u.cita a WHERE a.id_paciente=r.id_paciente AND a.estado IN('SCHEDULED','CHECKED_IN') AND tstzrange(a.programada_para,a.programada_para+interval '1 hour','[)') && tstzrange(s.inicia_a,s.termina_a,'[)')) THEN RAISE EXCEPTION 'El paciente ya tiene una cita activa en ese horario' USING ERRCODE='23505'; END IF; INSERT INTO salud_u.cita(id_paciente,id_cupo,tipo_cita,id_personal_asignado,programada_para) VALUES(r.id_paciente,s.id,r.tipo_cita,s.id_personal,s.inicia_a) RETURNING id INTO id_cita_creada; UPDATE salud_u.cupo_disponibilidad SET cantidad_reservada=cantidad_reservada+1,actualizado_en=now() WHERE id=s.id; UPDATE salud_u.solicitud_cita SET estado='ASSIGNED',id_cita=id_cita_creada,asignado_en=now(),asignado_por=actor WHERE id=r.id; INSERT INTO salud_u.evento_estado_cita(id_cita,estado_nuevo,id_actor) VALUES(id_cita_creada,'SCHEDULED',actor); RETURN id_cita_creada; END; $$;
REVOKE ALL ON TABLE salud_u.cita,salud_u.evento_estado_cita FROM PUBLIC; REVOKE ALL ON TABLE salud_u.cita,salud_u.evento_estado_cita FROM ${runtime_role}; REVOKE ALL ON FUNCTION salud_u.asignar_solicitud_cita(uuid,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION salud_u.asignar_solicitud_cita(uuid,uuid) TO ${runtime_role};
